package org.eclipse.rdf4j.sail.features;

import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.IdentityValueMappingBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class CompactSequentialLookupTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	private MapBindingSet source(String... names) {
		MapBindingSet row = new MapBindingSet();
		for (int i = 0; i < names.length; i++)
			row.addBinding(names[i], VF.createLiteral(i));
		return row;
	}

	private void same(BindingSet source, BindingSet copy, String name) {
		assertSame(source.getValue(name), copy.getValue(name));
	}

	@Test
	void sequentialCyclesAndForeignEqualStrings() {
		var source = source("a", "b", "c");
		var copy = CompactBindingSetSnapshot.copy(source);
		for (int n = 0; n < 10; n++)
			for (String s : List.of("a", "b", "c"))
				same(source, copy, new String(s));
	}

	@Test
	void repeatedAndOutOfOrderLookups() {
		var source = source("a", "b", "c");
		var copy = CompactBindingSetSnapshot.copy(source);
		for (String s : List.of("b", "b", "b", "a", "c", "a", "a", "c", "b", "a"))
			same(source, copy, s);
	}

	@Test
	void missingNullAndUnboundDoNotInventBindings() {
		var source = source("a", "b", "c");
		var copy = CompactBindingSetSnapshot.copy(source);
		for (int n = 0; n < 5; n++) {
			same(source, copy, "a");
			assertNull(copy.getValue("absent"));
			assertNull(copy.getValue(null));
			same(source, copy, "b");
			assertFalse(copy.hasBinding("unbound"));
			same(source, copy, "c");
		}
		var empty = CompactBindingSetSnapshot.copy(new MapBindingSet());
		assertNull(empty.getValue("a"));
		assertNull(empty.getValue(null));
	}

	@Test
	void collidingAndNegativeHashStrings() {
		String negative = "polygenelubricants";
		assertTrue(negative.hashCode() < 0);
		assertEquals("Aa".hashCode(), "BB".hashCode());
		var source = source("Aa", "BB", "AaAa", "BBBB", negative);
		var copy = CompactBindingSetSnapshot.copy(source);
		for (int n = 0; n < 20; n++)
			for (String s : List.of("BB", negative, "AaAa", "Aa", "BBBB", "BB"))
				same(source, copy, new String(s));
		assertNull(copy.getValue("AaBB"));
	}

	@Test
	void randomizedPermutationsAndMissingNames() {
		String[] names = new String[64];
		for (int i = 0; i < names.length; i++)
			names[i] = "v" + i;
		var source = source(names);
		var copy = CompactBindingSetSnapshot.copy(source);
		Random random = new Random(621);
		for (int i = 0; i < 10000; i++) {
			String name = random.nextInt(10) == 0 ? "missing" : new String(names[random.nextInt(names.length)]);
			same(source, copy, name);
		}
	}

	@Test
	void predictionChangesOnlyOnSuccessfulLookup() throws Exception {
		var copy = CompactBindingSetSnapshot.copy(source("a", "b", "c"));
		var field = CompactBindingSetSnapshot.class.getDeclaredField("nextLookupIndex");
		field.setAccessible(true);
		copy.getValue(new String("a"));
		int hint = field.getInt(copy);
		assertEquals(Boolean.getBoolean("rdf4j.sail.compactSequentialLookup") ? 1 : 0, hint);
		copy.getValue(null);
		copy.getValue("missing");
		assertEquals(hint, field.getInt(copy));
		copy.getValue("c");
		assertEquals(0, field.getInt(copy));
	}

	@Test
	void publicBindingViewsSwitchToOrdinaryMapSemantics() {
		for (String operation : List.of("binding", "iterator", "names")) {
			var source = source("a", "b", "c");
			MapBindingSet copy = (MapBindingSet) CompactBindingSetSnapshot.copy(source);
			same(source, copy, "b");
			if (operation.equals("binding"))
				copy.getBinding("a");
			else if (operation.equals("iterator"))
				copy.iterator();
			else
				copy.getBindingNames();
			for (String name : List.of("c", "a", "b", "a"))
				same(source, copy, name);
			Value changed = VF.createLiteral("changed");
			copy.setBinding("b", changed);
			assertSame(changed, copy.getValue("b"));
			copy.removeBinding("a");
			assertNull(copy.getValue("a"));
			copy.addBinding("z", changed);
			assertSame(changed, copy.getValue("z"));
		}
	}

	@Test
	void reentrantMappingReadsAndCallbackMutation() {
		MapBindingSet copy = (MapBindingSet) CompactBindingSetSnapshot.copy(source("a", "b", "c"));
		Value first = copy.getValue("a"), last = copy.getValue("c"), replacement = VF.createLiteral("replaced");
		List<Value> visited = new ArrayList<>();
		var mapped = ((IdentityValueMappingBindingSet) copy).mapValuesPreservingIdentity(value -> {
			visited.add(value);
			assertNotNull(copy.getValue(new String("c")));
			assertNotNull(copy.getValue("a"));
			if (visited.size() == 1)
				copy.setBinding("b", replacement);
			return value;
		});
		assertSame(copy, mapped);
		assertEquals(3, visited.size());
		assertSame(first, visited.get(0));
		assertSame(replacement, visited.get(1));
		assertSame(last, visited.get(2));
		assertSame(replacement, copy.getValue("b"));
	}

	@Test
	void pureNestedMappingLeavesOwnedValuesAndLookupsIntact() {
		var source = source("a", "b", "c");
		var copy = (IdentityValueMappingBindingSet) CompactBindingSetSnapshot.copy(source);
		assertSame(copy, copy.mapValuesPreservingIdentity(v -> {
			assertSame(copy, copy.mapValuesPreservingIdentity(inner -> {
				same(source, copy, new String("c"));
				same(source, copy, "a");
				return inner;
			}));
			return v;
		}));
		for (String s : List.of("a", "b", "c"))
			same(source, copy, s);
		source.clear();
		assertNotNull(copy.getValue("a"));
	}

	@Test
	void assertionsDisabledNullValueBindings() {
		if (CompactSequentialLookupTest.class.desiredAssertionStatus())
			return;
		MapBindingSet source = new MapBindingSet();
		source.addBinding("a", null);
		source.addBinding("b", VF.createLiteral("b"));
		var copy = CompactBindingSetSnapshot.copy(source);
		assertTrue(copy.hasBinding("a"));
		for (int i = 0; i < 5; i++) {
			assertNull(copy.getValue("a"));
			same(source, copy, "b");
			assertNull(copy.getValue("absent"));
		}
	}
}
